message.content:
{
  "definition_simple": "列車や電車が走るための鉄のレール。",
  "definition_standard": "鉄道車両が走行するための軌道。二本の鉄筋を敷いたもの。",
  "pos": "n",
  "semantic_class": "concrete",
  "sentences": [
    {
      "tier": "T1",
      "sentence": "電車が線路を走ります。"
    },
    {
      "tier": "T1",
      "sentence": "線路の近く危ないです。"
    },
    {
      "tier": "T2",
      "sentence": "子供たちが線路の石を見ています。"
    },
    {
      "tier": "T2",
      "sentence": "線路を渡るときは気をつけましょう。"
    },
    {
      "tier": "T3",
      "sentence": "彼は毎朝、線路沿いの道を歩いて通勤している。"
    },
    {
      "tier": "T4",
      "sentence": "大雨の影響で、一時的に線路の点検が行われた。"
    },
    {
      "tier": "T4",
      "sentence": "古い線路の撤去作業が深夜に行われる予定だ。"
    },
    {
      "tier": "T5",
      "sentence": "その町では、かつて路面電車の線路が道路の真ん中を走っていた。"
    },
    {
      "tier": "T6",
      "sentence": "鉄道会社は、冬の豪雪による線路の凍結を防ぐための設備を導入した。"
    },
    {
      "tier": "T6",
      "sentence": "都市計画の変更に伴い、鉄道路線の高架化と旧線路跡地の再開発が進められている。"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "primary_collocate": "渡る",
  "collocation_distractors": [
    {
      "word": "食べる",
      "reason": "「食べる」は飲食物を口に入れる動作であり、施設やインフラである線路の動作としては意味が完全に成立しないため。"
    },
    {
      "word": "読む",
      "reason": "「読む」は文字や文章を対象とする動詞であり、物理的な空間や構造物である線路に対して使うことができないため。"
    },
    {
      "word": "着る",
      "reason": "「着る」は衣類を身体にまとう動作であり、鉄道の軌道を意味する線路とは共起関係を結ばないため。"
    }
  ],
  "collocation_wrong_collocate": "走る",
  "cloze_distractors": [
    {
      "word": "道路",
      "reason": "「道路」は自動車や歩行者が通る道であり、電車が走る専用の軌道を指す文脈では不適切。"
    },
    {
      "word": "空",
      "reason": "「空」は上空の大気圏を指し、地上を走る電車が移動する場所としては意味が通じない。"
    },
    {
      "word": "海",
      "reason": "「海」は水域を指し、通常の鉄道車両がその上を走る場所としては文脈に適合しない。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼は線路を美味しく食べた。",
      "reason": "「線路」は食べ物ではないため、「食べる」という動詞の目的語として意味論的に不適格である。"
    },
    {
      "sentence": "線路が青いシャツを着ている。",
      "reason": "「線路」は衣服を着用する生物や対象ではないため、「着る」という述語と共起できない。"
    },
    {
      "sentence": "本棚の線路をきれいに掃除した。",
      "reason": "「線路」は屋外の鉄道用地に存在するものであり、屋内の家具である「本棚」の中に存在するのは状況としてあり得ない。"
    }
  ],
  "spot_incorrect": {
    "sentence": "電車が線路を泳いでいる。",
    "error_description": "「泳ぐ」という動作は水中で生物が行うものであり、鉄の軌道を走る電車には使用できないため、動詞の選択が誤っている。",
    "corrected": "電車が線路を走っている。"
  },
  "word_family_forms": [],
  "word_family_fake_forms": [
    "線路化する",
    "線路性",
    "線路さ"
  ],
  "syn_ant_candidates": [
    {
      "candidate": "軌道",
      "type": "synonym"
    },
    {
      "candidate": "レール",
      "type": "synonym"
    }
  ],
  "particle_candidates": [
    {
      "particle": "を",
      "is_correct": true,
      "explanation": "移動の動詞（渡る、走るなど）の起点が通過する場所を示す場合、移動域を表す格助詞「を」を使うのが正しい。"
    },
    {
      "particle": "に",
      "is_correct": false,
      "explanation": "「に」は着点や存在場所を示すことが多く、線路という空間を横断・移動する動作の直接の経路を表すには不適切。"
    },
    {
      "particle": "で",
      "is_correct": false,
      "explanation": "「で」は動作の手段や場所（舞台）を表すため、「線路を渡る」のような横断の経路を示す文脈では適切ではない。"
    },
    {
      "particle": "が",
      "is_correct": false,
      "explanation": "「が」は主格を示す助詞であり、この位置に入れると線路自体が主語になってしまい文意が通らなくなる。"
    }
  ]
}
